	applyUiScale(uiScaleValue - 0.10)
	saveConfig()
end)
ScaleMinus.Activated:Connect(function()
	applyUiScale(uiScaleValue - 0.10)
	saveConfig()
end)
ScalePlus.MouseButton1Click:Connect(function()
	applyUiScale(uiScaleValue + 0.10)
	saveConfig()
end)
ScalePlus.Activated:Connect(function()
	applyUiScale(uiScaleValue + 0.10)
	saveConfig()
end)

